import{_ as t,o,c as a,a2 as r}from"./chunks/framework.hw3Av5Vn.js";const f=JSON.parse('{"title":"FollowChords","description":"","frontmatter":{},"headers":[],"relativePath":"generators/FOLLOW_CHORDS.md","filePath":"generators/FOLLOW_CHORDS.md"}'),h={name:"generators/FOLLOW_CHORDS.md"};function s(n,e,d,i,c,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="followchords" tabindex="-1">FollowChords <a class="header-anchor" href="#followchords" aria-label="Permalink to &quot;FollowChords&quot;">​</a></h1><p>FollowChords moves a clip&#39;s notes to the chords another track plays, so that a song&#39;s chords are written once, in one place, and everything else follows them. Its Chords From names the track followed.</p><h2 id="chords-track" tabindex="-1">Chords Track <a class="header-anchor" href="#chords-track" aria-label="Permalink to &quot;Chords Track&quot;">​</a></h2><p>Put the song&#39;s chords on a track of their own, called Chords here, and turn that track&#39;s Mute on in the track editor so that the chords are a guide and make no sound. In each scene, the Chords track&#39;s clip says what the chords are, in either of two ways. The chords can be written by hand, a step a chord, with the step&#39;s Degree as the chord&#39;s root and its Chord row as the chord. Or the pattern can hold one chord and a <a href="./PROGRESSION">Progression</a> in that clip&#39;s chain can make the progression from it. FollowChords reads the chords as they come out of the Chords track, after that track&#39;s own chain, so the two ways are followed alike.</p><h2 id="following" tabindex="-1">Following <a class="header-anchor" href="#following" aria-label="Permalink to &quot;Following&quot;">​</a></h2><p>Write a figure over chord I, a bar of bass, an arpeggio or a held chord, and add FollowChords to a chain on its clip. As each note starts, FollowChords finds the chord most lately started on the track followed, in the same scene, and moves the note up the clip&#39;s scale by as many notes as that chord&#39;s root is above the scale&#39;s root. The scale decides whether a chord is major or minor, as with a Progression: a figure written on A in A minor plays F, A and C over a chord on F. Where the track followed plays a chord from outside the scale, such as E major in A minor, a note of the figure that is a third, a fifth or a seventh above the figure&#39;s root takes the chord&#39;s own note, so the figure plays G sharp. Rests, rhythm, velocity and gates stay as written.</p><p>A chord goes on through the rests after it, until the next chord starts. Before the first chord of a scene, with no track chosen, or in a scene where the track followed has no clip, nothing moves. A drum pattern is left alone. Tracks cannot follow each other in a circle.</p><p>Change a chord on the Chords track and every clip that follows it changes with it.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Name</td><td><code>ENTER</code> renames it, and every chain using it follows.</td></tr><tr><td>Chords from</td><td>The track whose chords are followed, a track of the current song. Renaming the track renames this too, and a track the song doesn&#39;t have moves nothing.</td></tr></tbody></table><h2 id="applying-the-generator" tabindex="-1">Applying the Generator <a class="header-anchor" href="#applying-the-generator" aria-label="Permalink to &quot;Applying the Generator&quot;">​</a></h2><p><code>examples/learning/24_follow_chords.yml</code> plays a band stuck on one chord and then following one muted track, SILENT Chords, one player at a time, with the chords written by hand and then made by a Progression.</p>',12)])])}const g=t(h,[["render",s]]);export{f as __pageData,g as default};
